function show_alert(t,e,r,i){let n=e;if("object"==typeof e){for(k in n="<ul>",e)n+="<li>"+e[k]+"</li>";n+="</ul>"}const o={title:t,html:n,icon:r,showConfirmButton:!0};i&&(o.timer=i,o.showConfirmButton=!1),Swal.fire(o)}function generate_alert(t,e){return'<div class="alert alert-dismissible alert-'+t+'" role="alert">'+e+'<button type="button" class="close" data-dismiss="alert" aria-label="Close"><span aria-hidden="true">&times;</span></button></div>'}function format_ribuan(t){if(0==(t=parseFloat(t.toString().replace(/\D/g,"")))||""==t)return 0;if(!t)return 0;let e="-"==t.toString().substr(0,1)?"-":"";var r=t.toString().split("").reverse().join("").match(/\d{1,3}/g);return e+(r=r.join(".").split("").reverse().join(""))}function setInt(t){return(t=parseFloat(t.replace(/\D/g,"")))||0}